const records = [];

// Extract features from the GeoJSON response
const features = $('Source 1').first().json.features;

for (let i = 0; i < features.length; i++) {
  const feature = features[i];

  // Extract fields from properties and geometry
  const id = feature.id;
  const magnitude = feature.properties.mag;
  const place = feature.properties.place;
  const time_ms = feature.properties.time;
  const longitude = feature.geometry.coordinates[0];
  const latitude = feature.geometry.coordinates[1];
  const depth_km = feature.geometry.coordinates[2];

  // Derive magnitude_band
  let magnitude_band;
  if (magnitude < 4.0) {
    magnitude_band = 'minor';
  } else if (magnitude >= 5.0) {
    magnitude_band = 'major';
  } else {
    magnitude_band = 'moderate';
  }

  // Create the record
  const record = {
    id,
    magnitude,
    place,
    time_ms,
    longitude,
    latitude,
    depth_km,
    magnitude_band
  };

  records.push(record);
}

return [{ json: { records } }];
